// Widths that are zero, negative or too large, and cells left over, in one table.
func TestSpansWidthEdgeCases(t *testing.T) {
	withTrueColor(t)
	cases := []struct {
		name   string
		widths []int
	}{
		{"zero width renders nothing", []int{0, 3, 0, 2}},
